import { useCallback } from '@wordpress/element';

import {
    CheckboxControl
} from '@wordpress/components';


export default function AdvancedPalette({
    ID,
    advancedPalettes,
    setAttributes
}) {

    const managerRef = useCallback(node => {

        if (!node) return;

        node.managerController.onAdvancedPalettesChange.add(
            ID + "_advancedPalettes",
            value => {
                setAttributes({ advancedpalettes: value });
            }
        );

        console.log(node);

    }, [setAttributes]);

    return <manager-provider
        manager-slug={ID}
        advanced-palettes={advancedPalettes}
        ref={managerRef}
    >
        <CheckboxControl
            __nextHasNoMarginBottom
            checked={advancedPalettes}
            label="Enable advanced palettes"
            onChange={(value) => { 
                setAttributes({ advancedpalettes: value });
            }}
        />
    </manager-provider>
}