import { useCallback } from '@wordpress/element';

/**
 * Control the palette by a palette dropdown.
 */
export default function Palettes({
    ID,
    palette,
    advancedPalettes,
    setAttributes
}) {

    const managerRef = useCallback(node => {
        if (!node) return;
        node.managerObject.palette.addListener(
            ID + "_palette",
            value => setAttributes({ palette: value })
        );
    }, [setAttributes, ID]);

    return <manager-provider
        palette={palette}
        manager-slug={ID}
        advanced-palettes={advancedPalettes}
        ref={managerRef}
    >
        <manager-palette-dropdown></manager-palette-dropdown>
    </manager-provider>

}